/**
 * GitLab + SSH deploy key e2e (`npm run e2e:gitlab`) against a real GitLab —
 * gitlab.com or a self-managed instance. Opt-in: it needs a GitLab account.
 *
 * Creates a throwaway project (initialized with a README), a project access
 * token, and — for the deploy-key path — a key generated by Conduit itself and
 * registered on the project with push access. Then, for each worker factory
 * (local worktree, and remote conduit-worker doing a fresh clone):
 *   1. Test Connection succeeds with the token, fails (with a hint, without
 *      echoing the token) with a bad one
 *   2. a `gitlab` repo syncs, and a run's agent pushes a branch over HTTPS
 *      with GITLAB_TOKEN/GITLAB_HOST in its env for glab
 *   3. an `sshkey` repo syncs and pins the host key (trust on first use), and
 *      a run's agent pushes a branch over SSH with the deploy key
 *   4. a tampered pinned host key fails the sync as a terminal auth error,
 *      and restoring it recovers
 * Every pushed branch is verified through the GitLab API. The project is
 * deleted afterwards.
 *
 * Env:
 *   GITLAB_E2E_URL      GitLab base URL (default https://gitlab.com)
 *   GITLAB_E2E_TOKEN    personal access token with `api` scope (required)
 *   GITLAB_E2E_NAMESPACE_ID  optional group id to create the project in
 *   GITLAB_E2E_FACTORIES     comma list, default "local,remote"
 *   CONDUIT_E2E_PORT, CONDUIT_E2E_PG as for the other suites.
 * A self-signed instance also needs its CA trusted by git (system store or
 * GIT_SSL_CAINFO) and Node (NODE_EXTRA_CA_CERTS).
 */
import WebSocket from 'ws'
import fs from 'node:fs'
import os from 'node:os'
import path from 'node:path'
import crypto from 'node:crypto'
import {
  repoRoot,
  stubBinDir,
  PG_BASE,
  ensureDatabase,
  requireBuild,
  startProcess,
  waitForOutput,
  stopProcess,
} from '../lib/harness.mjs'

const GL = (process.env.GITLAB_E2E_URL || 'https://gitlab.com').replace(/\/$/, '')
const GL_TOKEN = process.env.GITLAB_E2E_TOKEN
const PORT = Number(process.env.CONDUIT_E2E_PORT) || 7570
const FACTORIES = (process.env.GITLAB_E2E_FACTORIES || 'local,remote').split(',').map((s) => s.trim()).filter(Boolean)
const WORKER_TOKEN = 'e2e-gitlab-worker-token'

if (!GL_TOKEN) {
  console.error('[e2e:gitlab] Set GITLAB_E2E_TOKEN to a GitLab personal access token with api scope.')
  process.exit(1)
}

const results = []
const check = (name, ok, detail = '') => {
  results.push({ name, ok })
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}${detail ? ' — ' + detail : ''}`)
  return ok
}

async function gitlab(method, apiPath, body) {
  const res = await fetch(`${GL}/api/v4${apiPath}`, {
    method,
    headers: { 'PRIVATE-TOKEN': GL_TOKEN, 'Content-Type': 'application/json' },
    body: body ? JSON.stringify(body) : undefined,
  })
  const text = await res.text()
  let json
  try {
    json = text ? JSON.parse(text) : undefined
  } catch {
    json = text
  }
  return { status: res.status, ok: res.ok, json }
}

async function createProject() {
  const name = `conduit-e2e-${crypto.randomBytes(3).toString('hex')}`
  const res = await gitlab('POST', '/projects', {
    name,
    path: name,
    visibility: 'private',
    initialize_with_readme: true,
    default_branch: 'main',
    ...(process.env.GITLAB_E2E_NAMESPACE_ID ? { namespace_id: Number(process.env.GITLAB_E2E_NAMESPACE_ID) } : {}),
  })
  if (!res.ok) throw new Error(`could not create GitLab project: HTTP ${res.status} ${JSON.stringify(res.json)}`)
  return res.json
}

/** A Developer-role project token — what we document for users. gitlab.com
 *  Free has no project tokens, so fall back to the suite's own PAT there. */
async function projectToken(projectId) {
  const expires = new Date(Date.now() + 2 * 86_400_000).toISOString().slice(0, 10)
  const res = await gitlab('POST', `/projects/${projectId}/access_tokens`, {
    name: 'conduit-e2e',
    scopes: ['api', 'read_repository', 'write_repository'],
    access_level: 30,
    expires_at: expires,
  })
  if (res.ok && res.json?.token) return { token: res.json.token, kind: 'project access token' }
  console.log(`[e2e:gitlab] project access tokens unavailable (HTTP ${res.status}); using the suite PAT`)
  return { token: GL_TOKEN, kind: 'personal access token' }
}

function connect(url) {
  const ws = new WebSocket(url)
  let nextId = 1
  const pending = new Map()
  const statusHistory = new Map()
  // Callbacks are stored under a fixed method name. Looking one up by the
  // run id from the socket and calling it reads to CodeQL as a method call
  // whose name is user-controlled.
  const statusWaiters = []
  const deliverStatus = (runId, payload) => {
    for (const waiter of statusWaiters) {
      if (waiter.runId === runId) waiter.onStatus(payload)
    }
  }
  ws.on('message', (data) => {
    const msg = JSON.parse(data.toString())
    if (msg.type === 'response' || msg.type === 'error') {
      const p = pending.get(msg.id)
      if (!p) return
      pending.delete(msg.id)
      if (msg.type === 'error') p.reject(new Error(msg.error))
      else p.resolve(msg.result)
    } else if (msg.type === 'event' && msg.channel === 'run:statusChange') {
      const runId = msg.payload?.runId
      const history = statusHistory.get(runId) ?? []
      history.push(msg.payload)
      statusHistory.set(runId, history)
      deliverStatus(runId, msg.payload)
    }
  })
  const invoke = (channel, ...args) =>
    new Promise((resolve, reject) => {
      const id = nextId++
      pending.set(id, { resolve, reject })
      ws.send(JSON.stringify({ type: 'invoke', id, channel, args }))
      setTimeout(() => pending.has(id) && (pending.delete(id), reject(new Error(`${channel} timed out`))), 120_000)
    })
  const waitRun = (runId, timeoutMs = 180_000) => {
    const done = (p) => ['completed', 'failed', 'stopped'].includes(p.status)
    const seen = (statusHistory.get(runId) ?? []).find(done)
    if (seen) return Promise.resolve(seen)
    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => reject(new Error(`run ${runId} did not finish`)), timeoutMs)
      statusWaiters.push({
        runId,
        onStatus(payload) {
          if (!done(payload)) return
          clearTimeout(timer)
          resolve(payload)
        },
      })
    })
  }
  return { ready: new Promise((res, rej) => (ws.on('open', res), ws.on('error', rej))), invoke, waitRun, close: () => ws.close() }
}

async function waitSync(invoke, repoId, want, timeoutMs = 180_000) {
  const deadline = Date.now() + timeoutMs
  let repo
  while (Date.now() < deadline) {
    repo = await invoke('repos:get', repoId)
    if (want.includes(repo?.syncStatus)) return repo
    await new Promise((r) => setTimeout(r, 500))
  }
  throw new Error(`repo ${repoId} never reached ${want.join('/')} (last: ${repo?.syncStatus} ${repo?.syncError ?? ''})`)
}

async function runPush(conduit, repo, branch, factory) {
  const agent = await conduit.invoke('agents:create', {
    name: `e2e-gitlab-${repo.authMethod}-${factory}`,
    runner: 'claude',
    prompt: `E2E_GIT_PUSH:${branch}`,
    envVars: {},
    mcpConfig: { mcpServers: {} },
    repositoryId: repo.id,
  })
  const run = await conduit.invoke('runs:start', agent.id)
  const final = await conduit.waitRun(run.id)
  const logText = JSON.stringify(await conduit.invoke('runs:getLog', run.id))
  return { agent, run, final, logText }
}

async function branchExists(projectId, branch) {
  return (await gitlab('GET', `/projects/${projectId}/repository/branches/${encodeURIComponent(branch)}`)).ok
}

async function exercise(factory, project, token) {
  const tag = `[${factory}]`
  const suffix = `${factory}-${crypto.randomBytes(2).toString('hex')}`
  const dbName = `conduit_e2e_gitlab_${factory}`
  await ensureDatabase(dbName)
  const dataDir = fs.mkdtempSync(path.join(os.tmpdir(), `conduit-e2e-gitlab-${factory}-`))
  const env = {
    PATH: `${stubBinDir}${path.delimiter}${process.env.PATH}`,
    PORT: String(PORT),
    CONDUIT_DATA_DIR: dataDir,
    DATABASE_URL: `${PG_BASE}/${dbName}`,
    DATABASE_SSL: 'disable',
    ...(factory === 'remote' ? { CONDUIT_WORKER_FACTORY: 'remote', CONDUIT_WORKER_TOKEN: WORKER_TOKEN } : {}),
  }
  const server = startProcess(`server-${factory}`, 'node', [path.join(repoRoot, 'out/server/index.js')], { env })
  let worker
  let conduit
  try {
    await waitForOutput(server, 'running at')
    conduit = connect(`ws://localhost:${PORT}/ws`)
    if (factory === 'remote') {
      worker = startProcess('worker', 'node', [path.join(repoRoot, 'out/worker/index.js')], {
        env: {
          PATH: env.PATH,
          CONDUIT_SERVER_URL: `ws://localhost:${PORT}/ws/worker`,
          CONDUIT_WORKER_TOKEN: WORKER_TOKEN,
        },
      })
      await waitForOutput(server, 'Worker connected')
    }
    await conduit.ready

    // ── GitLab access token over HTTPS ──
    const httpUrl = project.http_url_to_repo
    const ok = await conduit.invoke('repos:testConnection', { url: httpUrl, authMethod: 'gitlab', gitlabToken: token })
    check(`${tag} gitlab: test connection with ${'token'}`, ok.success, ok.message)
    const bad = await conduit.invoke('repos:testConnection', { url: httpUrl, authMethod: 'gitlab', gitlabToken: 'glpat-not-a-real-token' })
    check(
      `${tag} gitlab: bad token fails with a hint and is not echoed`,
      !bad.success && /expired or been revoked/.test(bad.message) && !bad.message.includes('glpat-not-a-real-token'),
      bad.message.split('\n').pop()
    )

    const glRepo = await conduit.invoke('repos:create', {
      name: `gl-token-${suffix}`,
      url: httpUrl,
      defaultBranch: 'main',
      authMethod: 'gitlab',
      gitlabToken: token,
    })
    check(`${tag} gitlab: token is write-only`, glRepo.hasGitlabToken === true && !JSON.stringify(glRepo).includes(token))
    const glReady = await waitSync(conduit.invoke, glRepo.id, ['ready', 'error'])
    check(`${tag} gitlab: repo syncs`, glReady.syncStatus === 'ready', glReady.syncError ?? '')

    const glBranch = `conduit-e2e-token-${suffix}`
    const glRun = await runPush(conduit, glRepo, glBranch, factory)
    check(`${tag} gitlab: run pushes over HTTPS`, glRun.final.status === 'completed' && glRun.logText.includes(`PUSHED ${glBranch}`),
      glRun.logText.match(/PUSH_FAILED[^"]*/)?.[0] ?? `status=${glRun.final.status}`)
    check(`${tag} gitlab: glab env injected`, glRun.logText.includes(`GITLAB_TOKEN=set GITLAB_HOST=${new URL(GL).origin}`))
    check(`${tag} gitlab: token never in run log`, !glRun.logText.includes(token))
    check(`${tag} gitlab: branch visible in GitLab`, await branchExists(project.id, glBranch))

    // ── SSH deploy key ──
    const pair = await conduit.invoke('repos:generateSshKey')
    const dk = await gitlab('POST', `/projects/${project.id}/deploy_keys`, {
      title: `conduit-e2e-${suffix}`,
      key: pair.publicKey,
      can_push: true,
    })
    check(`${tag} sshkey: deploy key registered on GitLab`, dk.ok, dk.ok ? pair.fingerprint : JSON.stringify(dk.json))

    const sshUrl = project.ssh_url_to_repo
    const sshTest = await conduit.invoke('repos:testConnection', { url: sshUrl, authMethod: 'sshkey', sshPrivateKey: pair.privateKey })
    check(`${tag} sshkey: test connection`, sshTest.success, sshTest.message)

    const sshRepo = await conduit.invoke('repos:create', {
      name: `gl-ssh-${suffix}`,
      url: sshUrl,
      defaultBranch: 'main',
      authMethod: 'sshkey',
      sshPrivateKey: pair.privateKey,
    })
    check(
      `${tag} sshkey: private key is write-only, public key exposed`,
      sshRepo.hasSshKey === true &&
        !JSON.stringify(sshRepo).includes('PRIVATE KEY') &&
        pair.publicKey.startsWith(sshRepo.sshPublicKey ?? '-') &&
        sshRepo.sshKeyFingerprint === pair.fingerprint
    )
    const sshReady = await waitSync(conduit.invoke, sshRepo.id, ['ready', 'error'])
    check(`${tag} sshkey: repo syncs`, sshReady.syncStatus === 'ready', sshReady.syncError ?? '')
    const pinned = sshReady.sshKnownHosts ?? ''
    check(`${tag} sshkey: host key pinned on first sync`, /\sssh-|\secdsa-/.test(pinned), pinned.split('\n')[0]?.slice(0, 60))

    const sshBranch = `conduit-e2e-ssh-${suffix}`
    const sshRun = await runPush(conduit, sshRepo, sshBranch, factory)
    check(`${tag} sshkey: run pushes over SSH`, sshRun.final.status === 'completed' && sshRun.logText.includes(`PUSHED ${sshBranch}`),
      sshRun.logText.match(/PUSH_FAILED[^"]*/)?.[0] ?? `status=${sshRun.final.status}`)
    check(`${tag} sshkey: GIT_SSH_COMMAND injected`, sshRun.logText.includes('GIT_SSH_COMMAND=set'))
    check(`${tag} sshkey: branch visible in GitLab`, await branchExists(project.id, sshBranch))

    // ── Pinned host key mismatch ──
    const host = pinned.split(/\s+/)[0]
    const impostor = (await conduit.invoke('repos:generateSshKey')).publicKey.split(' ').slice(0, 2).join(' ')
    await conduit.invoke('repos:update', sshRepo.id, { sshKnownHosts: `${host} ${impostor}` })
    const mismatched = await waitSync(conduit.invoke, sshRepo.id, ['error'])
    check(`${tag} sshkey: changed host key is refused`, /host key/i.test(mismatched.syncError ?? ''), mismatched.syncError)
    await conduit.invoke('repos:update', sshRepo.id, { sshKnownHosts: pinned })
    // The re-sync starts asynchronously, so the previous `error` is still visible at first.
    const recovered = await waitSync(conduit.invoke, sshRepo.id, ['ready'], 60_000).catch((err) => ({ syncError: err.message }))
    check(`${tag} sshkey: restoring the pinned key recovers`, recovered.syncStatus === 'ready', recovered.syncError ?? '')

    for (const r of [glRun, sshRun]) await conduit.invoke('agents:delete', r.agent.id).catch(() => {})
    for (const r of [glRepo, sshRepo]) await conduit.invoke('repos:delete', r.id).catch(() => {})
  } finally {
    conduit?.close()
    if (worker) await stopProcess(worker)
    await stopProcess(server)
    fs.rmSync(dataDir, { recursive: true, force: true })
  }
}

async function main() {
  requireBuild('out/server/index.js', 'out/worker/index.js')
  const project = await createProject()
  console.log(`[e2e:gitlab] Created ${project.web_url}`)
  try {
    const { token, kind } = await projectToken(project.id)
    console.log(`[e2e:gitlab] Using a ${kind} for the gitlab auth method`)
    for (const factory of FACTORIES) await exercise(factory, project, token)
  } finally {
    const del = await gitlab('DELETE', `/projects/${project.id}`)
    console.log(`[e2e:gitlab] Deleted project (HTTP ${del.status})`)
  }
  const failed = results.filter((r) => !r.ok)
  console.log(`\n${results.length - failed.length}/${results.length} checks passed`)
  process.exit(failed.length ? 1 : 0)
}

main().catch((err) => {
  console.error('[e2e:gitlab] FAILED:', err)
  process.exit(1)
})
